import { useState } from "react";

function TodoRow({ todo }) {
  const [note, setNote] = useState("");          // state lives in each row.
  return (
    <li>
      <span>{todo.title}</span>
      <label>
        Note for {todo.title}
        <input value={note} onChange={(e) => setNote(e.target.value)} />
      </label>
    </li>
  );
}

export function TodoList({ todos, sortBy }) {
  const shown = todos.toSorted((a, b) => a[sortBy].localeCompare(b[sortBy]));
  return (
    <ul>
      {shown.map((todo) => (
        <TodoRow key={todo.id} todo={todo} />   // stable id from the data.
      ))}
    </ul>
  );
}
```

| Key choice | Safe when |
|---|---|
| `todo.id` from data. | always (preferred). |
| index. | list is static: never sorted, filtered, inserted into or deleted from. |
| `Math.random()`. | never: a new key every render remounts every row. |

